from django.contrib.contenttypes.models import ContentType
from django.urls import reverse

from bloomerp.models.files import FileNode
from bloomerp.tests.base import (
    BloomerpModuleViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestBloomerpFileListView(BloomerpModuleViewTestCase):
    """Tests class `BloomerpFileListView` from `bloomerp/views/generic/model/file_list.py`."""

    view_name = "files"
    module = "files"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Verify that the file library initializes the dataview with URL synchronization."""
        endpoint = reverse("components_dataview", kwargs={
            "content_type_id": ContentType.objects.get_for_model(FileNode).pk,
        })
        return [
            RequestScenario(
                name="File library loads the FileNode dataview with URL synchronization",
                user=self.admin_user,
                expected=ExpectedResult(response_validators=[
                    self.contains_text(f'hx-get="{endpoint}"'),
                    self.contains_text('"X-Bloomerp-Sync-Url": "true"'),
                ]),
            ),
        ]
